import{_ as i,c as e,o as a,ag as o}from"./chunks/framework.DPDPlp3K.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"old/模块化开发.md","filePath":"old/模块化开发.md"}'),r={name:"old/模块化开发.md"};function t(u,l,n,p,d,s){return a(),e("div",null,l[0]||(l[0]=[o('<h2 id="标题备选" tabindex="-1">标题备选 <a class="header-anchor" href="#标题备选" aria-label="Permalink to &quot;标题备选&quot;">​</a></h2><ol><li>JavaScript 基础补课：模块化开发，核心知识点一次讲清楚</li><li>前端人绕不开：模块化开发 从概念到代码示例</li><li>手把手梳理 模块化开发：面试和实战都能用上</li></ol><h2 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to &quot;摘要&quot;">​</a></h2><p>这篇文章适合前端基础巩固和面试复习，围绕「模块化开发」整理概念、示例和易混点，帮助你把 JavaScript 基础打扎实。</p><h2 id="正文" tabindex="-1">正文 <a class="header-anchor" href="#正文" aria-label="Permalink to &quot;正文&quot;">​</a></h2><p>哈喽大家好👋 我是程序🦍kk。把复杂知识掰成大白话讲明白，是我一直以来的小追求✨；<strong>打好基础才能稳步进阶</strong>，是我始终秉持的学习理念～</p><blockquote><p>📢 我搭建了5000人程序猿专属学习交流群 群内会同步前端开发/全栈开发/Web3开发/远程工作等干货资源 关注我并回复 <strong>加群</strong> ，就能加入交流圈啦🚀</p></blockquote><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p><strong>前端基础不是背概念，而是知道每个知识点在代码里怎么用。</strong></p><p>JavaScript 的知识点很多：语法、事件、正则、面向对象、异步、模块化、性能优化，每一块都能影响真实项目。</p><p>这篇围绕「模块化开发」把原始笔记重新梳理成更适合阅读和复习的版本。</p><h2 id="知识点整理" tabindex="-1">知识点整理 <a class="header-anchor" href="#知识点整理" aria-label="Permalink to &quot;知识点整理&quot;">​</a></h2><p>下面进入正文。代码示例建议直接敲一遍，很多细节只有运行起来才会真正记住。</p><p>如果你正在准备前端面试，可以把这里的代码示例当作复习清单逐个过一遍。</p><h2 id="没有模块化开发的时候" tabindex="-1">没有模块化开发的时候 <a class="header-anchor" href="#没有模块化开发的时候" aria-label="Permalink to &quot;没有模块化开发的时候&quot;">​</a></h2><ul><li>问题： <ol><li>没有办法维护</li><li>全局变量污染</li><li>依赖关系不清</li><li>必须按顺序引入文件</li></ol></li></ul><h2 id="iife-伪模块化标准-2003-2011" tabindex="-1">IIFE 伪模块化标准(2003~2011) <a class="header-anchor" href="#iife-伪模块化标准-2003-2011" aria-label="Permalink to &quot;IIFE 伪模块化标准(2003~2011)&quot;">​</a></h2><ul><li>Immediaitely Invoked Function Expression</li><li>自执行函数<code>(function () {})()</code></li><li>解决问题: <ol><li>依赖不清 <ul><li>直接在自执行函数的参数位置，能看到依赖了哪些模块</li></ul></li><li>变量全局污染 <ul><li>你后面的代码该用什么变量用什么</li></ul></li></ol></li><li>问题: <ol><li>文件顺序不能动</li><li>只能知道我依赖的几个模块，但是模块在哪个文件中不好说</li></ol></li></ul><h2 id="commonjs-模块化标准" tabindex="-1">CommonJS 模块化标准 <a class="header-anchor" href="#commonjs-模块化标准" aria-label="Permalink to &quot;CommonJS 模块化标准&quot;">​</a></h2><ul><li>2009 年，nodejs 出现了</li><li>使用JS去做服务端语言</li><li>伴生的是 CommonJS 模块化标准</li><li>缺点:只能在后端JS里面用</li></ul><h2 id="amd-模块化标准-依赖前置" tabindex="-1">AMD 模块化标准 - 依赖前置 <a class="header-anchor" href="#amd-模块化标准-依赖前置" aria-label="Permalink to &quot;AMD 模块化标准 - 依赖前置&quot;">​</a></h2><ul><li><p>Async Module Definition</p></li><li><p>2011出现的，社区里面发起的</p></li><li><p>因为非官方，没有关键字，大家书写了一套叫做 require.js 的第三方文件</p></li><li><p>来实现模块化标准</p></li><li><p>把每一个js文件独立出来了</p></li><li><p>使用了导入导出的语法来实现模块化</p></li><li><p>在JS文件里面引入另一个JS文件</p></li><li><p>页面只需要引入最后的整合文件就可以了</p></li><li><p>语法：</p><ul><li><p>定义模块(调用define 的方法)</p><ol><li><p>独立模块定义</p><ul><li>每一个模块文件开始执行define()</li><li>我不依赖其他文件，我就是一个单纯的模块</li><li>向外暴露的内容，直接return 出去就好了</li></ul></li><li><p>依赖其他模块的模块(我也是一个模块文件，但是我依赖的以他模块的内容)</p><ul><li>使用define() 定义</li><li>语法: <code>define([ 依赖文件1,依赖文件2, ... ], function (模块A,模块B) {})</code></li></ul></li></ol></li><li><p>导入其他模块</p><ul><li>使用这个方法require()</li><li>语法: <code>require([ 依赖文件1,依赖文件2, ... ], function (模块1, 模块2){})</code></li></ul></li></ul></li><li><p>解决问题:</p><ol><li><p>依赖很清晰</p><ul><li>因为只有一个文件，那么所有的东西都在一个文件里面出现</li></ul></li><li><p>变量全局污染</p><ul><li>没有全局污染，都在私有作用域</li></ul></li></ol></li><li><p>问题:</p><ul><li>依赖前置 <ul><li>不管多少行以后使用的东西，都会在打开页面的时候就加再进来</li><li>缺点：首屏加载时间长</li><li>优点：后期操作流畅</li></ul></li></ul></li></ul><h2 id="cmd-通用模块定义-即时依赖" tabindex="-1">CMD 通用模块定义 - 即时依赖 <a class="header-anchor" href="#cmd-通用模块定义-即时依赖" aria-label="Permalink to &quot;CMD 通用模块定义 - 即时依赖&quot;">​</a></h2><ul><li><p>Common Module Defineion</p></li><li><p>2011左右，社区里面出现的一个标准</p></li><li><p>淘宝&quot;玉伯&quot;，开发一了个CMD的模块化标准</p></li><li><p>依赖于一个叫做sea.js的文件来实现的模块化标准</p></li><li><p>使用:文件需要引入一个sea.js的文件</p><ol><li>独立模块定义 <ul><li>define( function ( require, exports, module) { }) <ul><li>require() 用来导入其他文件的</li><li>module.exports是为了本文件导出内容的</li><li>exports是module. exports的别名</li><li>var exports = module。exports</li></ul></li></ul></li><li>依赖其他模块的模块 <ul><li>你需要依赖其他文件模块 <ul><li>在define( function ( require, exports, module) {</li><li>在你需要的位置使用require() 方法来导入</li><li>var modA = require( &#39;地址’)</li></ul></li></ul></li><li>资源整合 <ul><li>使用seajs.use()</li><li>语法: seajs.use([&#39;你要 依赖的模块&#39;]，function (模块A) {})</li></ul></li></ol></li><li><p>解决问题</p><ul><li>依赖前置</li><li>按需加载，在你需要的时候，在加载</li><li>也留下了依赖前置的接口</li></ul></li><li><p>问题:</p><ul><li>即时依赖 <ul><li>首屏加载快</li><li>操作不够流畅</li></ul></li></ul></li></ul><h2 id="es6-module-依赖前置" tabindex="-1">ES6 Module - 依赖前置 <a class="header-anchor" href="#es6-module-依赖前置" aria-label="Permalink to &quot;ES6 Module - 依赖前置&quot;">​</a></h2><ul><li>2015年发布，ES6 语法里面自带了一个模块化标准</li><li>各大浏览器厂商并不买账</li><li>2016年开始，Vue出现了，人家出现了一个脚手架(开发的大框架直接给你搭建好)</li><li>搭建这个架子的时候，内置了ES6模块化标准</li><li>2018 年，各大浏览器厂商开始原生支持ES6模块化标准</li><li>2018 年中，Chrome 率先原生支持ES6模块化</li><li>变成了JS的语法，和关键字，不需要任何第三方文件的引入 <ul><li>特点:页面必须在服务器上打开 <ul><li>live server 插件</li><li>如果你想使用模块化语法，script 标签要加一个属性type=&quot; module&quot;</li></ul></li></ul></li></ul><h2 id="语法" tabindex="-1">语法 <a class="header-anchor" href="#语法" aria-label="Permalink to &quot;语法&quot;">​</a></h2><ol><li>每一个文件都可以作为独立模块，页都可以作为整合文件</li><li>导出语法 <ol><li>export default 导出的内容</li><li>export var num = 200</li></ol></li><li>导入语法 <ol><li>接收export default 导出 <ul><li><code>import 变量 from&#39;哪一个JS文件&#39;</code></li></ul></li><li>接收export导出的那个 <ul><li><code>import {接收变量} from&#39; 哪-一个JS文件&#39;</code></li></ul></li></ol></li></ol><h2 id="es2020-发布新标准" tabindex="-1">ES2020 发布新标准 <a class="header-anchor" href="#es2020-发布新标准" aria-label="Permalink to &quot;ES2020 发布新标准&quot;">​</a></h2><ul><li>多了一个按需加载的模块化</li><li>语法: <code>import(你要加载的文件).then(function(res){})</code></li></ul><h2 id="写在最后" tabindex="-1">写在最后 <a class="header-anchor" href="#写在最后" aria-label="Permalink to &quot;写在最后&quot;">​</a></h2><p>好啦，今天的分享就到这里！</p><p>💬 互动时间：</p><p>你最近复习 JavaScript 最头疼的是原型链、事件循环、正则，还是异步？评论区留一个关键词，后面可以单独展开。</p><p>最后，感谢你看到这里👏</p><p>如果喜欢这篇内容，不妨顺手给小编安排一波👇 <strong>点赞</strong>👍｜<strong>转发</strong>📲｜<strong>推荐</strong>❤️｜<strong>评论</strong>📣</p><p>要是想第一时间蹲到新内容推送，记得给我点个<strong>星标</strong>⭐️</p><p>更多干货内容正在持续填坑中，咱们下期见👋</p><h2 id="标签建议" tabindex="-1">标签建议 <a class="header-anchor" href="#标签建议" aria-label="Permalink to &quot;标签建议&quot;">​</a></h2><p>模块化开发、编程相关、JavaScript、前端基础</p>',40)]))}const m=i(r,[["render",t]]);export{c as __pageData,m as default};
